package glitch

import data.glitch_lib

has_public_ip(node) {
    walk(node, [_, n])
    n.ir_type == "String"
    n.value == "0.0.0.0"
}

check_wildcard(value) {
    value.ir_type == "String"
    value.value == "*"
} else {
    value.ir_type == "Array"
    count([e | e := value.value[_]; e.ir_type == "String"; e.value == "*"]) > 0
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    vars := glitch_lib.all_variables(parent)
    var := vars[_]
    has_public_ip(var.value)
    result := {
        "type": "sec_invalid_bind",
        "element": var,
        "path": parent.path,
        "description": "Public bind address - Service bound to 0.0.0.0, allowing public access. (CWE-284)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]
    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]
    has_public_ip(attr.value)
    result := {
        "type": "sec_invalid_bind",
        "element": attr,
        "path": parent.path,
        "description": "Public bind address - Service bound to 0.0.0.0, allowing public access. (CWE-284)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]
    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]
    regex.match("(?i)(action|resource|principal|permission)", attr.name)
    check_wildcard(attr.value)
    result := {
        "type": "sec_invalid_bind",
        "element": attr,
        "path": parent.path,
        "description": "Wildcard permission in policy - Avoid using wildcards in actions, resources, or principals. (CWE-284)"
    }
}
